context.report({
  node,
  messageId: 'topLevel',
  suggest: [
    {
      fix: fixerOne,
      messageId: 'suggestionOne',
      data: { placeholder1: 'value1' },
    },
    {
      fix: fixerTwo,
      messageId: 'suggestionTwo', // ✅
      data: { placeholder1: 'value1' },
    },
  ],
});
```
